// Vapi manda el cuerpo de dos formas distintas segun el tipo de tool:
//  - "API Request": JSON plano con los parametros + los Static Body Fields.
//  - Custom tool clasico: { message: { toolCallList: [ { id, name, arguments } ] } }
// Aceptamos las dos para no depender de cual se configure.
const raw = $json.body || $json || {};
const msg = raw.message || {};
const llamada = (msg.toolCallList || msg.toolCalls || [])[0] || {};

let args = llamada.arguments || (llamada.function && llamada.function.arguments) || null;
if (typeof args === 'string') {
  try { args = JSON.parse(args); } catch (e) { args = null; }
}

const datos = args || raw;
const nombre = llamada.name || (llamada.function && llamada.function.name) || '';

// Si Vapi no resuelve una plantilla Liquid, el valor llega literal como
// "{{ assistant.id }}". Lo tratamos como vacío en vez de propagar la basura.
const limpio = (v) => {
  const s = String(v == null ? '' : v).trim();
  return s.includes('{{') ? '' : s;
};

return [{
  json: {
    tool_call_id: llamada.id || raw.tool_call_id || '',
    herramienta: String(nombre).toLowerCase(),
    accion_pedida: String(datos.accion || '').toLowerCase(),
    // Identificamos al cliente por el assistant de Vapi que ha atendido la
    // llamada: así las mismas tools sirven para todos los clientes.
    assistant_id: limpio(datos.assistant_id) ||
      limpio(msg.assistant && msg.assistant.id) ||
      limpio(msg.call && msg.call.assistantId),
    // Numero de quien llama, util para poner nombre a la cita.
    telefono: limpio(datos.telefono) ||
      limpio(msg.call && msg.call.customer && msg.call.customer.number),
    client_id: limpio(datos.client_id),
    fecha: datos.fecha || null,
    hora: datos.hora || null,
    email: datos.email || null,
    nombre: limpio(datos.nombre),
    motivo: limpio(datos.motivo),
  },
}];

const d = $('Leer tool call').first().json;

// El client_id explicito en los argumentos manda; si no, el que hemos buscado
// por assistant_id en Supabase.
const encontrado = $input.first().json.client_id || '';
const clientId = d.client_id || encontrado;

return [{
  json: {
    ...d,
    client_id: clientId,
    // La acción puede venir del nombre de la tool o de un static body field.
    accion: (d.accion_pedida || d.herramienta).includes('reserv')
      ? 'reservar'
      : 'disponibilidad',
    contacto: d.nombre || d.telefono || 'Llamada de voz',
  },
}];

