const pet = $('Preparar llamada').first().json;
const api = $input.first().json || {};

// "ok" responde a "¿ha funcionado la herramienta?", no a "¿la respuesta es que
// sí?". Que una hora esté ocupada es una consulta correcta con un no por
// respuesta: si eso viaja como ok:false, Vapi lo lee como que la tool ha
// fallado y el agente improvisa en vez de leer el mensaje que le damos.
// El resultado de la consulta va aparte, en hay_hueco y reservada.
let texto = api.mensaje;
let ok = true;

if (!pet.client_id || api.motivo === 'cliente_desconocido') {
  ok = false;
  texto = 'No encuentro la configuración de este negocio. Avisa al administrador.';
} else if (!texto) {
  ok = false;
  texto = 'Ahora mismo no puedo consultar la agenda. Inténtalo de nuevo en un momento.';
}

const hayHueco = ok && (
  api.libre === true ||
  api.reservada === true ||
  (Array.isArray(api.dias) && api.dias.length > 0)
);

// Devolvemos las dos formas a la vez: "mensaje" plano para el tipo API Request
// (que extrae variables del JSON) y el sobre "results" con el toolCallId, que
// es lo que exige el custom tool clásico. Sobra una u otra, pero no estorban.
return [{
  json: {
    ok,
    mensaje: texto,
    hay_hueco: hayHueco,
    reservada: api.reservada === true,
    results: [{ toolCallId: pet.tool_call_id, result: texto }],
  },
}];
